<span class="line"><span style="color:#C678DD;">def</span><span style="color:#61AFEF;"> f</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;font-style:italic;">x</span><span style="color:#ABB2BF;">):  </span><span style="color:#7F848E;font-style:italic;"># 目标函数</span></span>
