<span class="line"><span style="color:#C678DD;">    return</span><span style="color:#ABB2BF;"> x1 </span><span style="color:#56B6C2;">**</span><span style="color:#D19A66;"> 2</span><span style="color:#56B6C2;"> +</span><span style="color:#D19A66;"> 2</span><span style="color:#56B6C2;"> *</span><span style="color:#ABB2BF;"> x2 </span><span style="color:#56B6C2;">**</span><span style="color:#D19A66;"> 2</span></span>
